ValidationRule.errorConditionFormula:
AND(
    NOT($User.BypassValidationRules__c),
    OR(
        AND(
            RecordType.DeveloperName = "OtherFeesGrid",
            OR(
                ISPICKVAL(Type__c, "SINGLE RULE"),
                ISPICKVAL(Type__c, "MULTI RULE")
            )
        ),
        AND(
            RecordType.DeveloperName <> "OtherFeesGrid",
            OR(
                ISPICKVAL(Type__c, "Courtage Assurance et Capi"),
                ISPICKVAL(Type__c, "Performance Fees")
            )
        )
    )
)
